UPDATE health_reports
mold_id = #{moldId}, report_title = #{reportTitle}, report_period_start = #{reportPeriodStart, typeHandler=com.zjb.mjgl.typehandler.LocalDateTypeHandler}, report_period_end = #{reportPeriodEnd, typeHandler=com.zjb.mjgl.typehandler.LocalDateTypeHandler}, total_usage_count = #{totalUsageCount}, total_production_time = #{totalProductionTime}, fault_count = #{faultCount}, repair_cost_total = #{repairCostTotal}, maintenance_completed_count = #{maintenanceCompletedCount}, maintenance_planned_count = #{maintenancePlannedCount}, maintenance_rate = #{maintenanceRate}, health_score = #{healthScore}, status = #{status}, pdf_file_path = #{pdfFilePath}, generated_by = #{generatedBy}, generated_at = #{generatedAt, typeHandler=com.zjb.mjgl.typehandler.LocalDateTimeTypeHandler}
WHERE id = #{id}

mapper.select:
SELECT *
FROM health_reports
WHERE mold_id = #{moldId}
  AND report_period_start = #{periodStart, typeHandler=com.zjb.mjgl.typehandler.LocalDateTypeHandler}
  AND report_period_end = #{periodEnd, typeHandler=com.zjb.mjgl.typehandler.LocalDateTypeHandler}
LIMIT 1

SELECT
    hr.*,
    m.mold_code AS mold_code,
    m.name AS mold_name
FROM health_reports hr
LEFT JOIN molds m ON hr.mold_id = m.id


        AND hr.mold_id = #{moldId}


        AND hr.status = #{status}


        AND hr.report_period_start >= #{periodStart, typeHandler=com.zjb.mjgl.typehandler.LocalDateTypeHandler}


        AND hr.report_period_end <= #{periodEnd, typeHandler=com.zjb.mjgl.typehandler.LocalDateTypeHandler}


        AND hr.health_score >= #{minHealthScore}


        AND hr.health_score <= #{maxHealthScore}


ORDER BY hr.generated_at DESC, hr.id
